 bx('pk','<b>Core problem:</b> banks see the <b>money trail</b>, customs sees the <b>goods trail</b>, enforcement sees the <b>criminal trail</b>. If they do not talk, TBML stays hidden.'),
 t('Challenges','Valuation difficulty','Shell-company networks; <b>beneficial ownership</b> opacity','Jurisdictional barriers; fake documents','Balance with <b>ease of doing business</b>',w=26),
 t('Way forward: "follow the goods, follow the money"','Integrate <b>Customs, banking, GST, DGFT, FIU and company-ownership</b> data for risk-based detection','Use <b>AI, price benchmarking, network analytics, anomaly detection</b>',w=26),
 sec('FATF BEST PRACTICES','g'),
 tb(['Practice','Meaning'],['<b>Risk-based national assessment</b>','Include TBML in National Risk Assessment (sectors, commodities, routes)'],['<b>Data integration</b>','Cross-match STRs, customs, shipping, invoices, ownership data'],['<b>Public-private partnership</b>','Trade data is scattered across banks, shippers, traders, government'],['<b>Red flags</b>','<b>FATF-Egmont</b> indicators: business structure, trade activity, documents and commodities, account activity'],['<b>Customs-FIU cooperation</b>','Goods intelligence plus money intelligence; e.g. <b>FIU-IND and SEBI MoU</b> for database sharing']),
